import{_ as i,o as s,c as l,a3 as n,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/import-export-statistik/export-schnittstellendateien-1.png",o="/bilder/import-export-statistik/export-schnittstellendateien-2-auswahlfenster.png",d="/bilder/import-export-statistik/import-schnittstellendateien.png",h="/bilder/import-export-statistik/import-schnittstellendateien-fehlerprotokoll.png",f=JSON.parse('{"title":"Daten über die SchILD-NRW-Schnittstelle austauschen","description":"","frontmatter":{"title":"Daten über die SchILD-NRW-Schnittstelle austauschen","source_pageid":354,"source_revision":5871},"headers":[],"relativePath":"schild3/import-export-statistik/schnittstelle-schild-nrw-verwaltung-export.md","filePath":"schild3/import-export-statistik/schnittstelle-schild-nrw-verwaltung-export.md"}'),c={name:"schild3/import-export-statistik/schnittstelle-schild-nrw-verwaltung-export.md"};function p(u,r,g,m,w,b){return s(),l("div",null,[...r[0]||(r[0]=[n('<h1 id="daten-uber-die-schild-nrw-schnittstelle-austauschen" tabindex="-1">Daten über die SchILD-NRW-Schnittstelle austauschen <a class="header-anchor" href="#daten-uber-die-schild-nrw-schnittstelle-austauschen" aria-label="Permalink to &quot;Daten über die SchILD-NRW-Schnittstelle austauschen&quot;">​</a></h1><p>Exportieren und importieren Sie die unterstützten Daten als Schnittstellendateien. Wählen Sie Verzeichnisse und Datenarten bewusst und beachten Sie die Importoptionen sowie das Fehlerprotokoll.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/export-schnittstellendateien-1.png"><img src="'+a+'" alt="Aufruf des Exportfensters." loading="lazy"></a></p><p><em>Aufruf des Exportfensters.</em></p><p><a href="/bilder/import-export-statistik/export-schnittstellendateien-2-auswahlfenster.png"><img src="'+o+'" alt="Auswahl, welche Schnittstellendateien mit welchen optionalen Einstellungen erzeugt werden sollen." loading="lazy"></a></p><p><em>Auswahl, welche Schnittstellendateien mit welchen optionalen Einstellungen erzeugt werden sollen.</em></p><p>Öffnen Sie <strong>Export → Allgemeine Exporte → Schnittstelle SchILD-NRW</strong>. Im Exportfenster wählen Sie aus, welche Daten in Schnittstellendateien gespeichert werden sollen.</p><p>Zuerst legen Sie ein <strong>Ausgabeverzeichnis</strong> fest.</p>',9),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),t("Tipp")]),e("p",null,[t("Nutzen Sie das "),e("em",null,"SVWS-Arbeitsverzeichnis"),t(" oder ein von mehreren Nutzern geteiltes Verzeichnis, ist es sehr wichtig, schon von Beginn an eine klare Ordnerstruktur abzusprechen.")])],-1),n("<p>Hier im Beispiel sollen unsere Dateien im Arbeitsverzeichnis im Unterordner <em>Export\\Schnittstellendateien</em> abgelegt werden.</p><ul><li><p>Über <strong>Vorhandene Export-Dateien vorher löschen</strong> ist festzulegen, ob im Ordner schon vorhandene Dateien gelöscht werden sollen. Diese Einstellung ist sinnvoll, wenn nur ein Teil der Daten exportiert wird. Würden existierende Dateien nicht gelöscht, könnten im Ordner zum einen die frisch exportierten Daten, aber auch andere, ältere Dateien zusammen existieren und im Laufe der nächsten Operationen zu Fehlern führen.</p></li><li><p>Der Schalter <strong>UTF8-kodierte Datei erzeugen</strong> legt fest, ob die Dateien als <em>ANSI</em> oder <em>UTF8 (Unicode)</em> kodiert werden. Für moderne Systeme macht es Sinn, UTF8 zu nutzen, jedoch kann es sein, dass ein anderes, älteres Programm, mit dem die Daten verarbeitet werden sollen, Unicode nicht unterstützt.</p></li></ul><p>Unter <strong>Zu exportierende Schüler</strong> stehen die Personen aus der aktuellen Schülerauswahl. Filtern Sie deshalb zuerst unter <strong>Schüler</strong> die gewünschte Gruppe und öffnen Sie danach den Export.</p><p>Im Fenster <strong>Zu exportierende Daten</strong> werden die Schnittstellendateien mit den gewünschten Inhalten ausgewählt.</p>",4),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),t("Tipp")]),e("p",null,[t("Sollen weniger als die Hälfte der Dateien erzeugt werden, hilft ein Klick auf "),e("strong",null,"Alle aus"),t(" unter dem Auswahlfenster, so dass die gewünschten Dateien mit weniger Klicks einfach angewählt werden können.")])],-1),n('<h2 id="weitere-export-optionen" tabindex="-1">Weitere Export-Optionen <a class="header-anchor" href="#weitere-export-optionen" aria-label="Permalink to &quot;Weitere Export-Optionen&quot;">​</a></h2><p>Weiterhin werden weitere <strong>Export-Optionen</strong> angeboten.</p><ul><li><p>Über <strong>Exportart für Schüler-Stammdaten</strong> wird gesteuert, welche Schule als die <em>Zuletzt besuchte Schule</em> eingetragen ist.</p><ul><li><strong>&quot;Normaler&quot; Export</strong>: Hier werden die Daten wie in der Datenbank übernommen.</li><li><strong>Schulwechsel-Export</strong>: Hier wird die eigene Schule als <em>Zuletzt besuchte Schule</em> eingetragen, da die Personen ja die eigene Schule mit dem Schulwechsel verlassen.</li></ul></li><li><p>Der Schalter <strong>Nur &quot;sichtbare&quot; Einträge exportieren</strong> beschränkt die betreffenden Katalogdaten auf sichtbare Einträge, soweit der jeweilige Katalog diese Eigenschaft unterstützt. Die frühere Sichtbarkeitssteuerung der Klassen- und Versetzungstabelle ist kein allgemeingültiges Beispiel für SchILD-NRW 3.</p></li><li><p><strong>Nur aktuellen Abschnitt exportieren</strong> beschränkt die Daten auf die des aktuellen Abschnitts.</p></li><li><p>In dieser Dateischnittstelle erfolgt die Zuordnung der Schüler über <em>Name, Vorname und Geburtsdatum</em>. Mit <strong>Klasse als zusätzliches Identifikationsmerkmal hinzufügen</strong> wird dieses Merkmal bei schülerbasierten Einträgen zusätzlich zur Verfügung gestellt.</p></li><li><p>Über <strong>Schuljahr von... bis</strong> lassen sich der für den Export relevante erste und letzte Abschnitt festlegen.</p></li><li><p>Wählen nach Festlegung der gewünschten Einstellungen <strong>Export starten</strong>.</p></li></ul><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/import-schnittstellendateien.png"><img src="'+d+'" alt="Auswahl der zu importierenden Daten." loading="lazy"></a></p><p><em>Auswahl der zu importierenden Daten.</em></p><p>Über <em>Verwaltung ➜ Import ➜ Schnittstelle SchILD-NRW</em> wird der Importprozess gestartet.</p><p>Zuerst ist ein <strong>Importverzeichnis</strong> zu wählen, in dem sich mit Schnittstellendateien kompatible Dateien befinden.</p>',8),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),t("Hinweis")]),e("p",null,[t("Dateinamen, Dateiformat und Datentypen der einzelnen Felder müssen der "),e("a",{href:"/schild3/import-export-statistik/schnittstellenbeschreibung.html"},"Schnittstellenbeschreibung"),t(" entsprechen. Andernfalls können die Dateien nicht korrekt importiert werden.")])],-1),n('<p>Nach der Verzeichnisauswahl zeigt <strong>Zu importierende Daten</strong> die gefundenen Dateien an. Im Beispiel enthält der Ordner nur einen Teil der möglichen Schnittstellendateien.</p><p>Wählen Sie per Haken die gewünschten Dateien an. Über <strong>Alle aus</strong> unter der Liste können alle Haken entfernt werden, um dann die gewünschten neu zu setzen.</p><ul><li>Unter <strong>Importart</strong> kann zwischen zwei Varianten gewählt werden: <ul><li><strong>Normaler Import</strong>: Es können alle Datenarten importiert werden, wobei fehlende Einträge in Katalogen automatisch angelegt werden.</li><li><strong>Schulwechsel-Import</strong>: Es können nur Daten importiert werden, die bei einem Schulwechsel von Schülern anfallen können. Dies sind die Schüler-Stammdaten, Erzieherdaten, Telefonumern und Adressen.</li></ul></li><li><strong>Keine Schüler neu anlegen</strong> verhindert, dass unerwartet neue Schüler erzeugt werden. Es werden nur vorhandene Daten aktualisiert.</li><li><strong>Keine Änderungen an vorhandenen Datensätzen</strong> verhindert das Überschreiben vorhandener Werte. Fehlende Datensätze beziehungsweise bislang leere Felder können laut Schnittstellenbeschreibung ergänzt werden. Unterscheiden Sie diese Option von <strong>Keine Schüler neu anlegen</strong> und beachten Sie die <a href="/schild3/import-export-statistik/schnittstelle-schild-vorbemerkungen.html#partielle-bzw-additive-importe">Regeln für partielle beziehungsweise additive Importe</a>. Prüfen Sie die gewählte Kombination vor einem umfangreichen Import an einem bekannten Datensatz.</li></ul><p><strong>Importieren</strong> startet den Import mit den gewählten Optionen.</p><h2 id="fehlerprotokoll" tabindex="-1">Fehlerprotokoll <a class="header-anchor" href="#fehlerprotokoll" aria-label="Permalink to &quot;Fehlerprotokoll&quot;">​</a></h2><p><a href="/bilder/import-export-statistik/import-schnittstellendateien-fehlerprotokoll.png"><img src="'+h+'" alt="Eventuell auftauchende Fehler werden im Fehlerprotokoll vermerkt." loading="lazy"></a></p><p><em>Eventuell auftauchende Fehler werden im Fehlerprotokoll vermerkt.</em></p><p>Tauchen beim Import bei einzelnen Datensätzen Fehler auf, werden diese nun in einem Fehlerprotokoll angezeigt.</p><p>Dieses lässt sich <em>Drucken</em> oder als Textdatei <em>Speichern</em>.</p><p>Nach dem Import sind <strong>Fehlerprotokoll und Stichprobe der Zieldaten</strong> zu prüfen; ein abgeschlossener Lauf belegt nicht die vollständige Übernahme aller Datensätze.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Schnittstelle_SchILD-NRW_(Verwaltung_Export)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5871.</p>',12)])])}const S=i(c,[["render",p]]);export{f as __pageData,S as default};
